namespace sv_b6b2d11fd4704b7889216b61ada7e2f8.Services;

public class WarehouseState
{
    public string CurrentWarehouseId { get; private set; } = "WH-001";
    public string CurrentWarehouseName { get; private set; } = "Warehouse A";

    public event Action? OnChange;

    public static readonly IReadOnlyDictionary<string, string> AvailableWarehouses =
        new Dictionary<string, string>
        {
            ["WH-001"] = "Warehouse A",
            ["WH-002"] = "Warehouse B",
            ["WH-003"] = "Warehouse C",
            ["WH-004"] = "Warehouse D",
        };

    public void SetWarehouse(string warehouseId)
    {
        if (AvailableWarehouses.TryGetValue(warehouseId, out var name)
            && warehouseId != CurrentWarehouseId)
        {
            CurrentWarehouseId = warehouseId;
            CurrentWarehouseName = name;
            OnChange?.Invoke();
        }
    }
}

namespace sv_b6b2d11fd4704b7889216b61ada7e2f8.Services;

/// <summary>
/// Scoped service that polls for low-stock alerts and notifies all subscribers.
/// Scoped lifetime ensures each circuit (user) has independent state.
/// </summary>
public class InventoryAlertService : IDisposable
{
    private readonly WarehouseState _warehouseState;
    private readonly Random _random = new();
    private Timer? _timer;
    private int _subscriberCount;

    public int LowStockCount { get; private set; }

    /// <summary>
    /// Fired from a background timer thread — subscribers must wrap
    /// StateHasChanged in InvokeAsync.
    /// </summary>
    public event Action? OnChange;

    public InventoryAlertService(WarehouseState warehouseState)
    {
        _warehouseState = warehouseState;
    }

    public Task<int> GetLowStockCountAsync(string warehouseId)
    {
        // Simulate a database query.
        return Task.FromResult(_random.Next(0, 16));
    }

    /// <summary>
    /// Reference-counted start: multiple components can call StartPolling and
    /// the timer only starts once. Stops when all subscribers call StopPolling.
    /// </summary>
    public void StartPolling()
    {
        _subscriberCount++;
        if (_timer is null)
        {
            _timer = new Timer(
                async _ => await PollAsync(),
                null,
                TimeSpan.Zero,
                TimeSpan.FromSeconds(10));
        }
    }

    public void StopPolling()
    {
        _subscriberCount = Math.Max(0, _subscriberCount - 1);
        if (_subscriberCount == 0)
        {
            _timer?.Dispose();
            _timer = null;
        }
    }

    private async Task PollAsync()
    {
        LowStockCount = await GetLowStockCountAsync(_warehouseState.CurrentWarehouseId);
        OnChange?.Invoke();
    }

    public void Dispose()
    {
        _timer?.Dispose();
        _timer = null;
    }
}

