@rendermode InteractiveServer
@implements IDisposable
@inject WarehouseState Warehouse
@inject InventoryAlertService Alerts

<PageTitle>Dashboard — @Warehouse.CurrentWarehouseName</PageTitle>

<h1>Warehouse Dashboard</h1>

<div class="row mt-4">
    <div class="col-md-4">
        <div class="card">
            <div class="card-body text-center">
                <h5 class="card-title">Current Warehouse</h5>
                <p class="display-6">@Warehouse.CurrentWarehouseName</p>
                <span class="text-muted">@Warehouse.CurrentWarehouseId</span>
            </div>
        </div>
    </div>

    <div class="col-md-4">
        <div class="card @(Alerts.LowStockCount > 0 ? "border-danger" : "border-success")">
            <div class="card-body text-center">
                <h5 class="card-title">Low-Stock Alerts</h5>
                <p class="display-4 @(Alerts.LowStockCount > 0 ? "text-danger" : "text-success")">
                    @Alerts.LowStockCount
                </p>
                <span class="text-muted">items below minimum levels</span>
            </div>
        </div>
    </div>

    <div class="col-md-4">
        <div class="card">
            <div class="card-body text-center">
                <h5 class="card-title">Polling Status</h5>
                <p class="display-6">🟢 Active</p>
                <span class="text-muted">refreshes every 10 s</span>
            </div>
        </div>
    </div>
</div>

@code {
    private Action? _alertHandler;
    private Action? _warehouseHandler;

    protected override void OnInitialized()
    {
        _alertHandler = () => InvokeAsync(StateHasChanged);
        Alerts.OnChange += _alertHandler;

        // Re-render when the warehouse changes so the heading updates immediately.
        _warehouseHandler = () => InvokeAsync(StateHasChanged);
        Warehouse.OnChange += _warehouseHandler;

        Alerts.StartPolling();
    }

    public void Dispose()
    {
        Alerts.OnChange -= _alertHandler;
        Warehouse.OnChange -= _warehouseHandler;
        Alerts.StopPolling();
    }
}

